class Solution:
    def minOperations(self, boxes: str) -> list[int]:
        n = len(boxes)
        ans = [0] * n

        count = 0
        ops = 0
        for i in range(n):
            ans[i] += ops
            if boxes[i] == '1':
                count += 1
            ops += count

        count = 0
        ops = 0
        for i in range(n - 1, -1, -1):
            ans[i] += ops
            if boxes[i] == '1':
                count += 1
            ops += count

        return ans

#include <vector>
#include <string>
using namespace std;

class Solution {
public:
    vector<int> minOperations(string boxes) {
        int n = boxes.size();
        vector<int> ans(n, 0);

        int count = 0, ops = 0;
        for (int i = 0; i < n; ++i) {
            ans[i] += ops;
            if (boxes[i] == '1') count++;
            ops += count;
        }

        count = 0; ops = 0;
        for (int i = n - 1; i >= 0; --i) {
            ans[i] += ops;
            if (boxes[i] == '1') count++;
            ops += count;
        }

        return ans;
    }
};

class Solution {
    public int[] minOperations(String boxes) {
        int n = boxes.length();
        int[] ans = new int[n];

        int count = 0, ops = 0;
        for (int i = 0; i < n; ++i) {
            ans[i] += ops;
            if (boxes.charAt(i) == '1') count++;
            ops += count;
        }

        count = 0; ops = 0;
        for (int i = n - 1; i >= 0; --i) {
            ans[i] += ops;
            if (boxes.charAt(i) == '1') count++;
            ops += count;
        }

        return ans;
    }
}

